// Run inside the browser on the page generated by nfn-fixture.mjs.
(async () => {
  const checks = [];
  const assert = (condition, label) => { if (!condition) throw new Error(label); checks.push(label); };
  const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
  const buttons = () => [...document.querySelectorAll("button")];
  const click = text => buttons().find(button => button.textContent === text).click();
  const nav = label => document.querySelector(`[aria-label="${label} notification"]`).click();
  const draft = text => { const input = document.querySelector("textarea"); input.value = text; input.dispatchEvent(new Event("input")); return input; };
  window.nfn.setPlacement({ placement: "right", max_width: 1000, max_height: 860, reduce_motion: true });
  window.nfn.collapse();
  window.fixture.calls.length = 0; window.fixture.contextCalls = 0;
  window.fixture.records.clear();
  window.fixture.records.set("first", window.fixture.record("first"));
  window.nfn.receive(window.fixture.snapshot("first"));
  document.querySelector("#surface").dispatchEvent(new MouseEvent("mouseenter"));
  assert(document.querySelectorAll(".actions button").length === 3, "first card exposes three quick choices");
  assert(document.querySelector(".reply-label").textContent === "Reply to agent" && document.querySelector(".send").textContent === "Send", "reply field and Send are visible on the first card");
  assert(!document.querySelector(".logs, .details-content, select") && window.fixture.contextCalls === 0, "first card has no logs, settings, or background log polling");
  assert(buttons().some(button => button.textContent === "Agent controls"), "agent controls are reachable on the first card");
  assert(getComputedStyle(document.querySelector(".send")).borderRadius === "20px" && document.querySelector(".send").offsetHeight < 38, "Send uses a small rounded action button");
  click("Agent controls"); await sleep(60);
  assert(document.querySelector('.menu-panel[role="dialog"] .model-controls select') && !document.querySelector(".details-content"), "agent controls open directly without expanding Details");
  document.querySelector('[aria-label="Close menu"]').click();
  assert(document.querySelector("#surface").getBoundingClientRect().height < 430, "first card stays compact");
  assert(!window.unsafeMarkup && !document.querySelector(".message img"), "request text cannot inject markup");
  const input = draft("Keep this draft");
  const second = window.fixture.record("second"); second.request.title = "Second request";
  window.fixture.records.set("second", second); window.nfn.receive(window.fixture.snapshot("second"));
  assert(document.querySelector("h1").textContent === "Review the launch post" && document.querySelector("textarea") === input, "new arrivals preserve the current card and input");
  nav("Next"); await sleep(30);
  assert(document.querySelector("h1").textContent === "Second request", "next notification is one click away");
  draft("Second draft"); nav("Previous"); await sleep(30);
  assert(document.querySelector("textarea").value === "Keep this draft", "switching cards preserves separate reply drafts");
  assert(!document.querySelector(".details-content") && document.querySelector(".count").textContent === "1 / 2", "navigation opens a simple card with a position count");
  document.querySelector("textarea").focus();
  document.dispatchEvent(new KeyboardEvent("keydown", { key: "]", metaKey: true, shiftKey: true })); await sleep(30);
  assert(document.querySelector("h1").textContent === "Second request" && document.activeElement === document.querySelector("textarea"), "keyboard switching keeps the reply field focused");
  nav("Previous"); await sleep(30);
  window.nfn.setPlacement({ placement: "right", max_width: 1000, max_height: 860, reduce_motion: false });
  const compactSize = document.querySelector("#surface").getBoundingClientRect();
  click("Details");
  const resize = document.querySelector("#surface").getAnimations()[0];
  assert(Boolean(resize), "Details starts an animated resize");
  resize.pause(); resize.currentTime = 100;
  const intermediateWidth = document.querySelector("#surface").getBoundingClientRect().width;
  assert(intermediateWidth > 400 && intermediateWidth < 620, "resize interpolates through intermediate widths");
  resize.finish(); await sleep(60);
  const detailSize = document.querySelector("#surface").getBoundingClientRect();
  assert(detailSize.width === 620 && detailSize.height > compactSize.height + 200, "Details expands both width and reading space");
  window.nfn.setPlacement({ placement: "right", max_width: 1000, max_height: 860, reduce_motion: true });
  assert(document.querySelector(".row .diff-add") && window.fixture.contextCalls > 0, "Details loads the custom layout and recent output on demand");
  assert(document.querySelector(".reply").getBoundingClientRect().bottom < document.querySelector(".details-content").getBoundingClientRect().top, "reply stays above the details scroller");
  assert(!document.querySelector("select"), "agent settings stay hidden even when viewing details");
  click("Agent controls"); await sleep(60);
  assert(document.querySelector(".model-controls select"), "advanced agent controls remain available behind a button");
  document.querySelector('[aria-label="Close menu"]').click();
  click("Hide details"); await sleep(30);
  const contextCalls = window.fixture.contextCalls; await sleep(1150);
  assert(window.fixture.contextCalls === contextCalls && !document.querySelector(".logs, select"), "closing details stops polling and hides extra controls");
  click("More choices (1)");
  assert(document.querySelectorAll(".actions button").length === 4, "additional choices are available without opening details");
  window.fixture.records.get("first").request.body = "Updated caption for review";
  window.nfn.receive(window.fixture.snapshot()); await sleep(30);
  assert(document.querySelector(".message").textContent === "Updated caption for review" && document.querySelector("textarea").value === "Keep this draft", "deduplicated updates preserve the reply draft");
  click("Send"); click("Send"); await sleep(60);
  const replies = window.fixture.calls.filter(command => command.op === "respond");
  assert(replies.length === 1 && replies[0].id === "first" && replies[0].text === "Keep this draft", "Send delivers the draft once to the selected request");
  assert(document.querySelector(".send").disabled, "sent cards disable repeat submission");
  await sleep(760);
  assert(document.querySelector("h1").textContent === "Second request" && document.querySelector("textarea").value === "Second draft", "successful replies advance to the next card and keep its draft");
  assert(document.querySelector(".count").textContent === "1 / 1", "the count excludes answered notifications");
  window.fixture.responseError = "Agent is busy";
  click("Send"); await sleep(60);
  assert(document.querySelector("textarea").value === "Second draft" && document.querySelector(".notice").textContent === "Agent is busy", "failed replies keep the draft and show the delivery error beside it");
  window.fixture.responseError = null;
  window.nfn.collapse();
  window.fixture.records.get("first").status = "pending";
  for (let i = 0; i < 65; i++) window.fixture.records.set(`burst-${i}`, window.fixture.record(`burst-${i}`));
  window.nfn.receive(window.fixture.snapshot()); window.nfn.receive({ type: "show" });
  assert(document.querySelectorAll(".queue-item").length === 50, "notification list loads a bounded page");
  const lastPageItem = document.querySelectorAll(".queue-item")[49]; lastPageItem.click(); await sleep(30);
  nav("Next"); await sleep(60);
  assert(document.querySelector(".count").textContent === "51 / 67", "next loads the next page without opening the notification list");
  window.nfn.receive({ type: "show" });
  assert(document.querySelectorAll(".queue-item").length === 67, "loaded notifications stay available in the list");
  click("History"); await sleep(60);
  assert(document.querySelector('[role="tab"][aria-selected="true"]').textContent === "History", "History has a selected segment");
  click("Pending"); await sleep(30);
  assert(document.querySelector('[role="tab"][aria-selected="true"]').textContent === "Pending" && document.querySelectorAll(".queue-item").length === 67, "switching from History back to Pending restores the pending list");
  click("History"); click("Pending"); window.nfn.receive(window.fixture.snapshot()); await sleep(60);
  assert(document.querySelector('[role="tab"][aria-selected="true"]').textContent === "Pending", "queue refreshes keep the selected segment");
  window.nfn.receive({ ...window.fixture.snapshot(), preview: true });
  document.querySelector(".queue-item").click(); await sleep(30);
  const responseCount = window.fixture.calls.filter(command => command.op === "respond").length;
  document.querySelector(".actions button").click(); await sleep(30);
  assert(window.fixture.calls.filter(command => command.op === "respond").length === responseCount, "preview actions never dispatch real responses");
  window.nfn.collapse();
  document.querySelector("#surface").dispatchEvent(new MouseEvent("mouseleave"));
  window.fixture.records.get("first").request.media = [{ kind: "video", src: "/tmp/clawtab-nfn-media-test.mp4" }];
  const mediaSnapshot = window.fixture.snapshot("first"); mediaSnapshot.templates.templates[0].layout.unshift({ type: "media" });
  window.nfn.receive(mediaSnapshot);
  assert(!document.querySelector("video"), "first cards do not load video");
  click("View attachment");
  const video = document.querySelector("video");
  assert(video && video.preload === "metadata", "attachment button loads video on demand");
  click("Hide details");
  assert(video.paused && !video.hasAttribute("src"), "closing details releases video playback");
  window.nfn.collapse();
  document.querySelector("#surface").dispatchEvent(new MouseEvent("mouseleave"));
  window.fixture.records.clear();
  const approval = window.fixture.record("approval", 3);
  approval.question_id = "approval-prompt";
  approval.request.body = "Old terminal output\n".repeat(30) + "Would you like to run the checks?\n$ echo 'ready?'\n1. Yes\n2. No";
  window.fixture.records.set(approval.id, approval);
  window.nfn.receive(window.fixture.snapshot(approval.id));
  assert(document.querySelector(".message").textContent === "Would you like to run the checks?\n$ echo 'ready?'", "detected prompts lead with the current question instead of old terminal output");
  assert(!document.querySelector('[role="switch"]'), "auto-yes stays out of the main card");
  document.querySelector('[aria-label="Notification options"]').click();
  const autoYes = document.querySelector('[role="switch"]');
  assert(autoYes && autoYes.getAttribute("aria-checked") === "false" && !document.querySelector(".details-content"), "the top-right options menu contains agent-scoped auto-yes");
  const contextCount = window.fixture.contextCalls;
  autoYes.click(); autoYes.click(); await sleep(60);
  assert(window.fixture.calls.filter(command => command.op === "auto_yes").length === 1 && autoYes.getAttribute("aria-checked") === "true", "auto-yes sends one command and reflects confirmed daemon state");
  assert(window.fixture.contextCalls === contextCount, "auto-yes state does not require loading logs");
  window.fixture.autoYesPanes.clear(); window.nfn.receive(window.fixture.snapshot());
  assert(autoYes.getAttribute("aria-checked") === "false", "auto-yes stays in sync with changes from another client");
  window.fixture.autoYesError = "Agent session changed";
  autoYes.click(); await sleep(60);
  assert(autoYes.getAttribute("aria-checked") === "false" && !autoYes.disabled && document.querySelector(".notice").textContent === "Agent session changed", "failed auto-yes keeps its actual state and shows the error");
  window.fixture.autoYesError = null;
  window.nfn.receive({ ...window.fixture.snapshot(), preview: true });
  const autoCalls = window.fixture.calls.filter(command => command.op === "auto_yes").length;
  autoYes.click(); await sleep(60);
  assert(window.fixture.calls.filter(command => command.op === "auto_yes").length === autoCalls && autoYes.getAttribute("aria-checked") === "false", "preview auto-yes is inert and never pretends to enable permissions");
  document.querySelector('[aria-label="Close menu"]').click();
  window.nfn.receive(window.fixture.snapshot());
  window.nfn.setPlacement({ placement: "notch", notch_width: 210, overlap: 38, max_width: 500, max_height: 600, reduce_motion: true });
  click("Details");
  const smallSize = document.querySelector("#surface").getBoundingClientRect();
  assert(smallSize.width === 500 && smallSize.height <= 600 && document.querySelector(".details-content").clientHeight > 100, "expanded details fit a small display and retain a usable scroller");
  assert(document.querySelector(".reply").getBoundingClientRect().bottom <= document.querySelector("#surface").getBoundingClientRect().bottom, "reply controls remain visible on a small display");
  assert(!document.querySelector("#surface").getAnimations().length, "Reduce Motion uses immediate size changes");
  window.nfn.collapse();
  const notchStyle = getComputedStyle(document.querySelector("#surface"));
  assert(notchStyle.backgroundColor === "rgb(0, 0, 0)" && notchStyle.borderTopWidth === "0px" && notchStyle.paddingTop === "38px" && parseFloat(notchStyle.width) === 210 && notchStyle.borderTopLeftRadius === "0px", "collapsed notch matches the cutout width and covers its full height without top corners or a border");
  document.querySelector("#surface").dispatchEvent(new MouseEvent("mouseleave"));
  const timedApproval = window.fixture.snapshot(approval.id); timedApproval.settings.preview_seconds = .05;
  window.nfn.receive(timedApproval); await sleep(180);
  assert(Boolean(document.querySelector(".card")), "actionable cards remain open beyond the preview timer");
  window.nfn.outsideClick();
  assert(Boolean(document.querySelector(".card")), "clicking another app keeps actionable cards available for review");
  window.nfn.collapse();
  window.fixture.records.clear();
  const update = window.fixture.record("update", 0); update.request.template = "update";
  update.request.actions = [{ id: "acknowledge", label: "Got it", kind: "choice" }];
  window.fixture.records.set(update.id, update);
  const timedUpdate = window.fixture.snapshot(update.id); timedUpdate.settings.preview_seconds = .05;
  window.nfn.receive(timedUpdate);
  assert(document.querySelector(".status").textContent === "Update" && !document.querySelector(".reply, .auto-yes") && document.querySelector(".actions button").textContent === "Got it", "status updates read as notices without asking for instructions");
  await sleep(180);
  assert(document.querySelector("#surface").classList.contains("pill"), "only status updates collapse on the preview timer");
  click("Notifications"); window.nfn.outsideClick(); await sleep(180);
  assert(Boolean(document.querySelector(".card")), "an explicitly opened update stays expanded while using another app");
  window.nfn.collapse();
  window.fixture.records.clear();
  const alert = window.fixture.record("capacity-alert", 0);
  alert.request.title = "ClawTab";
  alert.request.body = "Selected model is at capacity. Please try a different model.";
  alert.request.template = "update";
  alert.request.data = { event: "agent_alert" };
  alert.request.actions = [{ id: "focus", label: "Open session", kind: "focus" }];
  window.fixture.records.set(alert.id, alert);
  const alertSnapshot = window.fixture.snapshot(alert.id); alertSnapshot.settings.preview_seconds = .05;
  window.nfn.receive(alertSnapshot);
  assert(document.querySelector(".status.alert").textContent === "! Alert" && getComputedStyle(document.querySelector(".status.alert")).color === "rgb(255, 135, 0)", "agent failures display an orange alert marker");
  assert(!document.querySelector(".reply, .auto-yes") && document.querySelector(".message").textContent === alert.request.body, "failure notices show the full error without approval controls");
  await sleep(180);
  assert(Boolean(document.querySelector(".card")), "agent alerts stay open until dismissed or recovered");
  click("Open session"); await sleep(30);
  assert(window.fixture.calls.some(command => command.op === "respond" && command.id === alert.id && command.action_id === "focus"), "the alert action opens its originating session");
  alert.status = "resolved";
  window.nfn.receive(window.fixture.snapshot());
  assert(document.querySelector(".status").textContent === "Recovered" && !document.querySelector(".status.alert"), "recovered agents clear the active warning");
  await sleep(180);
  assert(document.querySelector("#surface").classList.contains("empty") && !document.querySelector(".card"), "recovered alerts close after briefly showing their resolved state");
  window.nfn.collapse();
  return { passed: checks.length, checks };
})()
